import random
import struct
from typing import List

# This generator produces valid ZeroMQ payload frames (arbitrary binary).
# Strategy:
# - Generate diverse but valid payloads that exercise different meaningful cases:
#   - Empty frame, tiny frames, typical text, UTF-8 with NULs, binary with full range bytes,
#     Z85-friendly sizes (multiples of 4), sizes around common thresholds.
# - Keep result size <= 4096 bytes.
# - Deterministic per seed, but with variety across seeds.

_MAX_TOTAL = 4096

def _rand(r: random.Random, a: int, b: int) -> int:
    return r.randint(a, b)

def _random_ascii(r: random.Random, n: int) -> bytes:
    # Printable ASCII including spaces, common punctuation
    alphabet = b"0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz !@#$%^&*()_+-=[]{}|;:'\",.<>/?\n\r\t"
    return bytes(r.choice(alphabet) for _ in range(n))

def _random_utf8(r: random.Random, n: int) -> bytes:
    # Mix of ASCII and multibyte UTF-8 sequences
    out = bytearray()
    while len(out) < n:
        t = r.random()
        if t < 0.6:
            out.append(r.randrange(0x20, 0x7f))
        elif t < 0.8:
            # 2-byte sequence
            cp = r.randrange(0x80, 0x7FF)
            out.extend(chr(cp).encode('utf-8'))
        elif t < 0.95:
            # 3-byte sequence
            cp = r.randrange(0x800, 0xFFFF)
            # avoid surrogates
            if 0xD800 <= cp <= 0xDFFF:
                cp = 0xE000
            out.extend(chr(cp).encode('utf-8'))
        else:
            # 4-byte sequence
            cp = r.randrange(0x10000, 0x10FFFF)
            out.extend(chr(cp).encode('utf-8'))
        # Occasionally inject NULs
        if r.random() < 0.1 and len(out) < n:
            out.append(0)
    return bytes(out[:n])

def _random_binary(r: random.Random, n: int) -> bytes:
    return bytes(r.randrange(0, 256) for _ in range(n))

def _z85_friendly_size(r: random.Random, min_n: int, max_n: int) -> int:
    # multiples of 4 (Z85 encoder input requirement)
    min_q = (min_n + 3) // 4
    max_q = max(1, max_n // 4)
    q = _rand(r, min_q, max_q)
    return q * 4

def _compose_parts(parts: List[bytes], r: random.Random) -> bytes:
    # Combine parts with optional delimiters like NUL, newline, or length headers
    out = bytearray()
    for i, p in enumerate(parts):
        # Optional prefix length header sometimes (big-endian 16-bit)
        if r.random() < 0.15 and len(out) + 2 + len(p) <= _MAX_TOTAL:
            out.extend(struct.pack('>H', len(p)))
        out.extend(p)
        if i != len(parts) - 1 and len(out) < _MAX_TOTAL:
            choice = r.random()
            if choice < 0.25:
                out.append(0)  # NUL
            elif choice < 0.5:
                out.extend(b"\n")
            elif choice < 0.75:
                out.extend(b"\r\n")
            # else no separator
        if len(out) >= _MAX_TOTAL:
            break
    return bytes(out[:_MAX_TOTAL])

def _make_payload(r: random.Random) -> bytes:
    # Choose a scenario
    scenarios = [
        "empty",
        "tiny_ascii",
        "small_binary",
        "utf8_with_nuls",
        "z85_block_binary",
        "repeated_patterns",
        "size_edges",
        "structured_mix",
    ]
    sc = r.choice(scenarios)

    if sc == "empty":
        return b""

    if sc == "tiny_ascii":
        n = _rand(r, 1, 16)
        return _random_ascii(r, n)

    if sc == "small_binary":
        n = _rand(r, 17, 256)
        return _random_binary(r, n)

    if sc == "utf8_with_nuls":
        n = _rand(r, 32, 512)
        return _random_utf8(r, n)

    if sc == "z85_block_binary":
        n = _z85_friendly_size(r, 4, 1024)
        return _random_binary(r, n)

    if sc == "repeated_patterns":
        # Common protocol-like tokens and boundaries
        tokens = [b"HELLO", b"WORLD", b"PING", b"PONG", b"SUBSCRIBE", b"UNSUB", b"ROUTER", b"DEALER"]
        tok = r.choice(tokens)
        pad_byte = r.randrange(0, 256)
        rep = _rand(r, 2, 64)
        chunk = tok + bytes([0]) + bytes([pad_byte]) * _rand(r, 0, 8)
        data = (chunk * rep)[:_MAX_TOTAL]
        return data

    if sc == "size_edges":
        # Sizes near interesting boundaries
        choices = [0, 1, 2, 3, 4, 7, 8, 15, 16, 31, 32, 63, 64, 127, 128, 255, 256, 512, 1024, 2048, 4095]
        n = r.choice(choices)
        if n == 0:
            return b""
        # Fill with a gradient over 0..255
        return bytes((i % 256 for i in range(n)))

    if sc == "structured_mix":
        parts = []
        # Header-like section
        hdr_len = _rand(r, 4, 64)
        hdr = _random_ascii(r, hdr_len)
        parts.append(hdr)
        # Optional metadata key-values
        for _ in range(_rand(r, 0, 4)):
            k = _random_ascii(r, _rand(r, 3, 10))
            v = _random_ascii(r, _rand(r, 0, 12))
            parts.append(k + b"=" + v)
        # Binary blob (possibly Z85-friendly)
        if r.random() < 0.5:
            blob_len = _z85_friendly_size(r, 4, 512)
        else:
            blob_len = _rand(r, 8, 1024)
        parts.append(_random_binary(r, blob_len))
        # Footer
        parts.append(_random_ascii(r, _rand(r, 0, 16)))
        payload = _compose_parts(parts, r)
        return payload

    # Fallback
    return _random_binary(r, _rand(r, 1, 256))


def generate(seed: int) -> bytes:
    r = random.Random(seed)
    payload = _make_payload(r)
    # Ensure size limit
    if len(payload) > _MAX_TOTAL:
        payload = payload[:_MAX_TOTAL]
    return payload
